CREATE DATABASE IF NOT EXISTS general_sales_db CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE general_sales_db;
CREATE TABLE IF NOT EXISTS users(id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100) NOT NULL, username VARCHAR(60) NOT NULL UNIQUE, password VARCHAR(255) NOT NULL, role ENUM('admin','staff') NOT NULL DEFAULT 'admin', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS products(id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(150) NOT NULL, sku VARCHAR(60) UNIQUE, category VARCHAR(100) DEFAULT 'General', description TEXT, cost DECIMAL(12,2) NOT NULL DEFAULT 0, price DECIMAL(12,2) NOT NULL DEFAULT 0, stock INT NOT NULL DEFAULT 0, low_stock INT NOT NULL DEFAULT 5, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS customers(id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(150) NOT NULL, phone VARCHAR(50), email VARCHAR(150), address TEXT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS suppliers(id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(150) NOT NULL, contact_person VARCHAR(120), phone VARCHAR(50), email VARCHAR(150), address TEXT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS sales(id INT AUTO_INCREMENT PRIMARY KEY, receipt_no VARCHAR(40) NOT NULL UNIQUE, customer_id INT NULL, total DECIMAL(12,2) NOT NULL, payment_method VARCHAR(40) DEFAULT 'Cash', sold_by INT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(customer_id) REFERENCES customers(id) ON DELETE SET NULL, FOREIGN KEY(sold_by) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS sale_items(id INT AUTO_INCREMENT PRIMARY KEY, sale_id INT NOT NULL, product_id INT NULL, product_name VARCHAR(150) NOT NULL, quantity INT NOT NULL, unit_price DECIMAL(12,2) NOT NULL, subtotal DECIMAL(12,2) NOT NULL, FOREIGN KEY(sale_id) REFERENCES sales(id) ON DELETE CASCADE, FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE SET NULL);
